import { createEntryPayload } from "./page";

export const EntriesPage = () => {
  const payload = createEntryPayload({
    entryId: "entry-1",
    name: "Draft",
    tags: ["new"],
    enabled: true,
  });

  return <pre>{JSON.stringify(payload)}</pre>;
};

/**
 * @summary entry 생성 payload 계약
 */
interface CreateEntryPayload {
  /**
   * @field entry 식별자
   */
  entryId: string;
  /**
   * @field entry 이름
   */
  name: string;
  /**
   * @field entry 태그 목록
   */
  tags: string[];
  /**
   * @field entry 활성화 여부
   */
  enabled: boolean;
}

/**
 * @helper entry 입력값을 생성 payload로 정규화
 */
export const createEntryPayload = (payload: CreateEntryPayload): CreateEntryPayload => {
  const { entryId, name, tags, enabled } = payload;

  return {
    entryId,
    name: name.trim(),
    tags,
    enabled,
  };
};
